//! Test tool: subscribes to the publisher's uProtocol topic and prints every
//! received uMessage as one JSON line on stdout. Shows that the publisher's
//! messages really arrive over Zenoh, without running the Guardian.
//!
//! Each line looks like
//! `{"rx_ms": ..., "sent_ms": ..., "latency_ms": 3, "source": "//vehicle/8001/1/8001",
//!   "message_id": "...", "sample": {"path": ..., "value": 24.65, "rolling_counter": 31}}`.
//!
//! Example: `vss-listen -c config/publisher.toml`

use std::str::FromStr;
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

use async_trait::async_trait;
use clap::Parser;
use up_rust::{UListener, UMessage, UTransport, UUri};
use vss_publisher::config::PublisherConfig;
use vss_publisher::publisher::zenoh_transport;

#[derive(Parser)]
struct Args {
    /// Publisher configuration (TOML), to know its uProtocol topic.
    #[arg(short, long)]
    config: Option<std::path::PathBuf>,
    /// Zenoh configuration (JSON5), overrides `uprotocol.zenoh_config`.
    #[arg(long)]
    zenoh_config: Option<String>,
}

/// Listener that prints every received uMessage.
struct Printer;

#[async_trait]
impl UListener for Printer {
    async fn on_receive(&self, msg: UMessage) {
        let rx_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_millis() as u64)
            .unwrap_or(0);
        // The uMessage id is a UUIDv7: it contains the time the publisher created it.
        let sent_ms = msg.id().and_then(|id| id.get_time());
        // Payload as generic JSON; anything else is shown as text.
        let sample = msg
            .payload
            .as_ref()
            .map(|p| {
                serde_json::from_slice(p).unwrap_or_else(|_| {
                    serde_json::Value::String(String::from_utf8_lossy(p).into_owned())
                })
            })
            .unwrap_or(serde_json::Value::Null);
        let line = serde_json::json!({
            "rx_ms": rx_ms,
            "sent_ms": sent_ms,
            "latency_ms": sent_ms.map(|s| rx_ms.saturating_sub(s)),
            "source": msg.source().map(|s| s.to_uri(false)),
            "message_id": msg.id().map(|id| id.to_hyphenated_string()),
            "sample": sample,
        });
        println!("{line}");
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    // Only warnings (e.g. from Zenoh) on stderr; stdout is for the messages.
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("warn")),
        )
        .with_writer(std::io::stderr)
        .init();
    let args = Args::parse();
    let cfg = match &args.config {
        Some(path) => PublisherConfig::load(path)?,
        None => PublisherConfig::default(),
    };
    let up = &cfg.uprotocol;
    let zenoh_config = args.zenoh_config.as_deref().or(up.zenoh_config.as_deref());
    let transport = zenoh_transport(&up.authority, zenoh_config).await?;

    // Same filter as the Guardian: any authority, the publisher's entity,
    // version and resource, e.g. //*/8001/1/8001.
    let filter = UUri::from_str(&format!(
        "//*/{:X}/{:X}/{:X}",
        up.entity_id, up.entity_version, up.resource_id
    ))?;
    transport
        .register_listener(&filter, None, Arc::new(Printer))
        .await?;
    eprintln!("listening on {}", filter.to_uri(false));
    // Messages are now printed by the listener; just wait for Ctrl-C.
    tokio::signal::ctrl_c().await?;
    Ok(())
}
